const webhookBody = $('Webhook').first().json.body;

// Merge로 들어온 items: pr / issue_comment / line_comment가 섞여있음
const prFiles = items.filter(i => i.json.type === 'pr' && i.json.patch);
const issueCommentsRaw = items.filter(i => i.json.type === 'issue_comment');
const lineCommentsRaw = items.filter(i => i.json.type === 'line_comment');

// diff 합치기
const combinedDiff = prFiles
  .map(i => `### File: ${i.json.filename} (Status: ${i.json.status})\nDiff:\n${(i.json.patch || '').slice(0, 1500)}`)
  .join('\n\n---\n\n');

// 댓글은 HTTP Request가 "한 item에 배열"로 줄 수도 있어서 평탄화
const flat = (arr) => {
  if (arr.length === 1 && Array.isArray(arr[0].json)) return arr[0].json;
  return arr.map(x => x.json);
};

const issueComments = flat(issueCommentsRaw);
const lineReviewComments = flat(lineCommentsRaw);

const cleanText = (s = '') =>
  String(s)
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<[^>]*>/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

const issueText = issueComments.length
  ? issueComments.map((c, idx) => {
      const author = c.user?.login ?? 'unknown';
      const at = c.created_at ?? '';
      return `[#${idx + 1}] ${author} ${at}\n${cleanText(c.body).slice(0, 1200)}`;
    }).join('\n\n---\n\n')
  : '없음';

const lineText = lineReviewComments.length
  ? lineReviewComments.map((c, idx) => {
      const author = c.user?.login ?? 'unknown';
      const at = c.created_at ?? '';
      const pos = c.path ? `${c.path}${c.line ? `:${c.line}` : ''}` : '';
      return `[#${idx + 1}] ${author} ${at}\n${pos}\n${cleanText(c.body).slice(0, 600)}`;
    }).join('\n\n---\n\n')
  : '없음';

const fileChangeComment = `## PR 일반 댓글(Conversation)\n${issueText}\n\n## PR 라인 댓글(Files changed)\n${lineText}`;

return [{
  json: {
    allFilesDiff: combinedDiff,
    totalFiles: prFiles.length,
    conversation: webhookBody,
    fileChangeComment,
  }
}];

const tree = $input.all()[0].json.tree;

const supportedExtensions = [
  '.ts', '.tsx',  // TypeScript
  '.js', '.jsx',  // JavaScript
  '.py',          // Python
  '.java',        // Java
  '.go',          // Go
];

const tsFiles = tree.filter(f => 
  f.type === 'blob' &&
  supportedExtensions.some(ext => f.path.endsWith(ext)) &&
  !f.path.includes('node_modules') &&
  !f.path.includes('.next') &&
  !f.path.includes('dist') &&
  !f.path.includes('build') &&
  !f.path.endsWith('.d.ts')
);

return [{ json: { files: tsFiles, count: tsFiles.length } }];

const importPatterns = {
  '.ts':   /import .+ from ['"](.+)['"]/g,
  '.tsx':  /import .+ from ['"](.+)['"]/g,
  '.js':   /import .+ from ['"](.+)['"]/g,
  '.jsx':  /import .+ from ['"](.+)['"]/g,
  '.py':   /(?:from\s+(\S+)\s+import|^import\s+(\S+))/gm,
  '.java': /import\s+([\w.]+);/g,
  '.go':   /import\s+["`](.+)["`]/g,
};

const getExt = (path) => '.' + path.split('.').pop();

const webhookData = $('Webhook').first().json.body;
const owner = webhookData.owner;
const repo = webhookData.repo;

const files = $input.all()[0].json.files;

const queries = files.map((f, i) => 
  `file${i}: object(expression: "HEAD:${f.path}") { ... on Blob { text } }`
).join('\n');

const query = `query { repository(owner: "${owner}", name: "${repo}") { ${queries} } }`;

return [{ 
  json: { 
    query,
    files: files.map(f => f.path),
  } 
}];

const data = $('HTTP Request1').first().json.data?.repository;
const fileList = $('import 추출').first().json.files;

const importPatterns = {
  '.ts':   /import .+ from ['"](.+)['"]/g,
  '.tsx':  /import .+ from ['"](.+)['"]/g,
  '.js':   /import .+ from ['"](.+)['"]/g,
  '.jsx':  /import .+ from ['"](.+)['"]/g,
  '.py':   /(?:from\s+(\S+)\s+import|^import\s+(\S+))/gm,
  '.java': /import\s+([\w.]+);/g,
  '.go':   /import\s+["`](.+)["`]/g,
};

const getExt = (path) => '.' + path.split('.').pop();

// pr_req에서 변경 파일 목록 가져오기
const changedFiles = $('pr_req2').all().filter(item => item.json.filename).map(item => item.json.filename);

const fileImports = {};
fileList.forEach((path, i) => {
  const content = data?.[`file${i}`]?.text || '';
  const ext = getExt(path);
  const pattern = importPatterns[ext];
  if (!pattern) return;
  pattern.lastIndex = 0;
  const imports = [...content.matchAll(pattern)]
    .map(m => m[1] || m[2])
    .filter(Boolean);
  fileImports[path] = imports;
});

const dependencyMap = {};
changedFiles.forEach(changed => {
  const changedName = changed.split('/').pop().replace(/\.(ts|tsx|js|jsx|py|java|go)$/, '');
  dependencyMap[changed] = [];
  fileList.forEach(path => {
    const imports = fileImports[path] || [];
    const isImporting = imports.some(imp => imp.includes(changedName));
    if (isImporting && path !== changed) {
      dependencyMap[changed].push(path);
    }
  });
});

return [{ json: { dependencyMap } }];

const dependencyMap = $input.all()[0].json.dependencyMap;

const changedFiles = new Set(Object.keys(dependencyMap));
const affectedFiles = new Set();
const impactCount = {};

Object.entries(dependencyMap).forEach(([src, targets]) => {
  impactCount[src] = targets.length;
  targets.forEach(t => affectedFiles.add(t));
});

const pureAffected = [...affectedFiles].filter(f => !changedFiles.has(f));
const warnFiles = [...changedFiles].filter(f => (impactCount[f] || 0) >= 2);
const normalChanged = [...changedFiles].filter(f => (impactCount[f] || 0) < 2);

const getName = (id) => id.split('/').pop();
const getDir = (id) => id.split('/').slice(0, -1).join('/');

const getSize = (id) => {
  if (!changedFiles.has(id)) return 22;
  const count = impactCount[id] || 0;
  if (count >= 3) return 55;
  if (count === 2) return 45;
  if (count === 1) return 32;
  return 22;
};

const getColor = (id) => {
  if (changedFiles.has(id) && (impactCount[id] || 0) >= 2) return '#f59e0b';
  if (changedFiles.has(id)) return '#ef4444';
  return '#3b82f6';
};

const allNodes = new Set([...changedFiles, ...affectedFiles]);
const nodes = [...allNodes].map(id => ({
  id, name: getName(id), fullPath: id,
  symbolSize: getSize(id),
  itemStyle: { color: getColor(id)},
  label: { show: true, fontSize: getSize(id) > 35 ? 12 : 10, color: '#000' }
}));

const edges = [];
Object.entries(dependencyMap).forEach(([src, targets]) => {
  targets.forEach(t => edges.push({
    source: src, target: t,
    lineStyle: {
      color: getColor(src) === '#f59e0b' ? '#f59e0b88' : '#47556988',
      width: (impactCount[src] || 0) >= 2 ? 2.5 : 1.5
    }
  }));
});

const warnItemsHtml = warnFiles
  .sort((a,b) => (impactCount[b]||0)-(impactCount[a]||0))
  .map(f => `<div class="file-item changed warn"><div class="file-name">${getName(f)}<span class="badge badge-warn">⚠️ →${impactCount[f]}개</span></div><div class="file-path">${getDir(f)}</div></div>`).join('');

const changedItemsHtml = normalChanged
  .map(f => {
    const count = impactCount[f] || 0;
    const badge = count > 0 ? `<span class="badge badge-red">→${count}개</span>` : '';
    return `<div class="file-item changed"><div class="file-name">${getName(f)}${badge}</div><div class="file-path">${getDir(f)}</div></div>`;
  }).join('');

const affectedItemsHtml = pureAffected
  .map(f => `<div class="file-item affected"><div class="file-name">${getName(f)}</div><div class="file-path">${getDir(f)}</div></div>`).join('');

const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <script src="https://cdnjs.cloudflare.com/ajax/libs/echarts/5.4.3/echarts.min.js"><\/script>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
      body { background: #f8fafc; color: #1e293b; font-family: "Segoe UI", monospace; display: flex; height: 100vh; overflow: hidden; } 
      /* ===== Sidebar ===== */ 
      #sidebar { width: 280px; min-width: 280px; background: #ffffff; border-right: 1px solid #e2e8f0; display: flex; flex-direction: column; overflow-y: auto; background: #fff; } 
      #sidebar-header { padding: 20px; border-bottom: 1px solid #e2e8f0; background: #f6f8fa; } 
      #sidebar-header h1 { font-size: 15px; color: #0f172a; font-weight: 700; } 
      #sidebar-header p { font-size: 11px; color: #64748b; margin-top: 4px; } 
      .stat-row { display: flex; gap: 8px; padding: 16px 20px; border-bottom: 1px solid #e2e8f0; } 
      .stat-box { flex: 1; background: #f6f8fa; border-radius: 8px; padding: 10px; text-align: center; } 
      .stat-box .num { font-size: 22px; font-weight: 700; } 
      .stat-box .label { font-size: 12px; color: #64748b; margin-top: 2px; } 
      .section-title { padding: 12px 20px 6px; font-size: 13px; font-weight:bold; color: #000; text-transform: uppercase; letter-spacing: 1px; } 
      .file-item { padding: 8px 20px; font-size: 12px; border-left: 3px solid transparent; } 
      .file-item.changed { border-left-color: #ef4444; } 
      .file-item.changed.warn { border-left-color: #f59e0b; background: #fff7ed; } 
      .file-item.affected { border-left-color: #3b82f6; } 
      .file-name { color: #1e293b; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } 
      .file-path { color: #94a3b8; font-size: 11px; margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } 
      .badge { display: inline-block; font-size: 9px; padding: 1px 6px; border-radius: 10px; margin-left: 4px; vertical-align: middle; } 
      .badge-warn { background: #ffedd5; color: #c2410c; } .badge-red { background: #fee2e2; color: #b91c1c; } 
      /* ===== Chart Area ===== */ 
      #chart-area { flex: 1; display: flex; flex-direction: column; background: #ffffff; } 
      #toolbar { padding: 12px 20px; border-bottom: 1px solid #e2e8f0; display: flex; align-items: center; gap: 16px; font-size: 12px; background: #f6f8fa; } 
      @media (max-width: 960px) { #toolbar { flex-direction: column; align-items: flex-start; } } 
      .legend-item { display: flex; align-items: center; gap: 6px; color: #475569; } 
      .legend-dot { width: 12px; height: 12px; border-radius: 50%; } 
      #chart { flex: 1; background: #ffffff; }
      /* ===== Tooltip ===== */ 
      #tooltip { position: fixed; background: #ffffff; border: 1px solid #e2e8f0; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08); border-radius: 8px; padding: 10px 14px; font-size: 12px; pointer-events: none; display: none; z-index: 100; max-width: 300px; } 
      #tooltip .t-name { color: #0f172a; font-weight: 600; margin-bottom: 4px; } 
      #tooltip .t-path { color: #64748b; font-size: 11px; word-break: break-all; } 
      #tooltip .t-type { font-size: 11px; margin-top: 6px; padding: 3px 8px; border-radius: 4px; display: inline-block; } 
      .type-warn { background: #ffedd5; color: #c2410c; } 
      .type-changed { background: #fee2e2; color: #b91c1c; } 
      .type-affected { background: #dbeafe; color: #1d4ed8; }
  </style>
</head>
<body>
<div id="sidebar">
  <div id="sidebar-header">
    <h1>🔍 PR 영향도 분석</h1>
    <p>변경 파일이 어디까지 영향을 주는지 추적</p>
  </div>
  <div class="stat-row">
    <div class="stat-box"><div class="num" style="color:#ef4444">${changedFiles.size}</div><div class="label">변경 파일</div></div>
    <div class="stat-box"><div class="num" style="color:#3b82f6">${pureAffected.length}</div><div class="label">영향 파일</div></div>
    <div class="stat-box"><div class="num" style="color:#f59e0b">${warnFiles.length}</div><div class="label">⚠️ 주의</div></div>
  </div>
  <div class="section-title">⚠️ 주의 — 영향 범위 큰 변경 파일</div>
  ${warnItemsHtml}
  <div class="section-title">변경된 파일</div>
  ${changedItemsHtml}
  <div class="section-title">영향받는 파일 (변경 안 됨)</div>
  ${affectedItemsHtml}
</div>
<div id="chart-area">
  <div id="toolbar">
    <span style="color:#64748b; font-size:12px;">드래그 이동 · 스크롤 줌 · 노드 크기 = 영향 범위</span>
    <div style="margin-left:auto; display:flex; gap:16px;">
      <div class="legend-item"><div class="legend-dot" style="background:#f59e0b"></div> 변경됨 + 영향 큼</div>
      <div class="legend-item"><div class="legend-dot" style="background:#ef4444"></div> 변경됨</div>
      <div class="legend-item"><div class="legend-dot" style="background:#3b82f6"></div> 영향받음</div>
    </div>
  </div>
  <div id="chart"></div>
</div>
<div id="tooltip">
  <div class="t-name" id="t-name"></div>
  <div class="t-path" id="t-path"></div>
  <div class="t-type" id="t-type"></div>
</div>
<script>
  const changedFiles = new Set(${JSON.stringify([...changedFiles])});
  const impactCount = ${JSON.stringify(impactCount)};
  const chart = echarts.init(document.getElementById('chart'));
  chart.setOption({
    backgroundColor: '#ffffff',
    series: [{
      type: 'graph', layout: 'force', roam: true, draggable: true,
      force: { repulsion: 320, edgeLength: [80, 180], gravity: 0.08 },
      nodes: ${JSON.stringify(nodes)},
      edges: ${JSON.stringify(edges)},
      edgeSymbol: ['none', 'arrow'], edgeSymbolSize: 8,
      emphasis: { focus: 'adjacency', lineStyle: { width: 3 } }
    }]
  });
  chart.on('mouseover', (p) => {
    if (p.dataType !== 'node') return;
    const d = p.data;
    const count = impactCount[d.id] || 0;
    document.getElementById('t-name').textContent = d.name;
    document.getElementById('t-path').textContent = d.fullPath;
    const typeEl = document.getElementById('t-type');
    if (changedFiles.has(d.id) && count >= 2) {
      typeEl.textContent = '⚠️ 변경됨 · ' + count + '개 파일에 영향';
      typeEl.className = 't-type type-warn';
    } else if (changedFiles.has(d.id)) {
      typeEl.textContent = count > 0 ? '변경됨 · ' + count + '개 파일에 영향' : '변경됨 · 영향 없음';
      typeEl.className = 't-type type-changed';
    } else {
      typeEl.textContent = '영향받는 파일 (변경 안 됨)';
      typeEl.className = 't-type type-affected';
    }
    document.getElementById('tooltip').style.display = 'block';
  });
  chart.on('mouseout', () => { document.getElementById('tooltip').style.display = 'none'; });
  document.addEventListener('mousemove', (e) => {
    const t = document.getElementById('tooltip');
    t.style.left = (e.clientX + 12) + 'px';
    t.style.top = (e.clientY + 12) + 'px';
  });
  window.addEventListener('resize', () => chart.resize());
<\/script>
</body>
</html>`;

return [{ json: { html } }];
